// ==========================================================
// CONFIGURATION - the only node you need to edit
// ==========================================================
const owner = 'YOUR_GITHUB_USERNAME';   // GitHub user or organisation
const repo = 'my-n8n-backup';           // PRIVATE repo, already initialised (at least one commit)
const branch = 'main';                  // target branch
const folder = 'workflows';             // folder holding the exports inside the repo

return [{ json: { owner: owner, repo: repo, branch: branch, folder: folder } }];

// ==========================================================
// Turn every workflow into a deterministic JSON file
// Goal: clean git diffs, no timestamp noise
// Archived workflows go to <folder>/archives/
// ==========================================================

const cfg = $('Configuration').first().json;
const folder = cfg.folder || 'workflows';

// Volatile or sensitive fields, stripped from the export.
// isArchived is kept on purpose: it is status, not noise.
const VOLATILE = [
  'createdAt', 'updatedAt', 'versionId', 'activeVersionId', 'triggerCount',
  'shared', 'sharedWithProjects', 'homeProject', 'scopes', 'canExecute',
  'usedCredentials', 'staticData', 'meta', 'pinData',
  'parentFolderId', 'nodeGroups', 'availableInMCP', 'activeVersion'
];

const ACCENTS = {
  'à': 'a', 'á': 'a', 'â': 'a', 'ã': 'a', 'ä': 'a', 'å': 'a',
  'è': 'e', 'é': 'e', 'ê': 'e', 'ë': 'e',
  'ì': 'i', 'í': 'i', 'î': 'i', 'ï': 'i',
  'ò': 'o', 'ó': 'o', 'ô': 'o', 'õ': 'o', 'ö': 'o',
  'ù': 'u', 'ú': 'u', 'û': 'u', 'ü': 'u',
  'ç': 'c', 'ñ': 'n', 'ý': 'y'
};

function deaccent(value) {
  return String(value).toLowerCase().replace(/[àáâãäåèéêëìíîïòóôõöùúûüçñý]/g, function (c) {
    return ACCENTS[c] || c;
  });
}

function slugify(value) {
  const base = deaccent(value || 'untitled')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+/, '')
    .replace(/-+$/, '')
    .slice(0, 60);
  return base || 'untitled';
}

// Recursive key sorting: two identical exports produce identical bytes
function sortKeys(value) {
  if (Array.isArray(value)) {
    return value.map(sortKeys);
  }
  if (value && typeof value === 'object') {
    const out = {};
    const keys = Object.keys(value).sort();
    for (let i = 0; i < keys.length; i++) {
      out[keys[i]] = sortKeys(value[keys[i]]);
    }
    return out;
  }
  return value;
}

const workflows = $input.all().map(function (item) { return item.json; });

if (!workflows.length) {
  throw new Error('n8n API returned no workflow: backup aborted so the repo is not wiped');
}

workflows.sort(function (a, b) { return String(a.id).localeCompare(String(b.id)); });

const files = [];
const liveRows = [];
const archivedRows = [];
let activeCount = 0;
let liveCount = 0;
let archivedCount = 0;

for (let i = 0; i < workflows.length; i++) {
  const wf = workflows[i];
  const archived = wf.isArchived === true;

  const clean = {};
  const keys = Object.keys(wf);
  for (let k = 0; k < keys.length; k++) {
    if (VOLATILE.indexOf(keys[k]) === -1) {
      clean[keys[k]] = wf[keys[k]];
    }
  }

  // Stable node order: n8n does not depend on it
  if (Array.isArray(clean.nodes)) {
    clean.nodes = clean.nodes.slice().sort(function (a, b) {
      return String(a.name).localeCompare(String(b.name));
    });
  }

  if (Array.isArray(clean.tags)) {
    clean.tags = clean.tags.map(function (t) {
      return t && t.name ? t.name : t;
    }).sort();
  }

  const dir = archived ? folder + '/archives' : folder;
  const path = dir + '/' + slugify(wf.name) + '.' + wf.id + '.json';
  const content = JSON.stringify(sortKeys(clean), null, 2) + '\n';

  files.push({ path: path, content: content });

  const safeName = String(wf.name || 'untitled').split('|').join('/');
  const nodeCount = Array.isArray(wf.nodes) ? wf.nodes.length : 0;

  if (archived) {
    archivedCount++;
    archivedRows.push('| ' + safeName + ' | `' + wf.id + '` | ' + nodeCount + ' | [json](' + path + ') |');
  } else {
    liveCount++;
    if (wf.active) { activeCount++; }
    liveRows.push('| ' + safeName + ' | `' + wf.id + '` | ' + (wf.active ? 'active' : 'inactive') + ' | ' + nodeCount + ' | [json](' + path + ') |');
  }
}

// The README carries no timestamp on purpose: it would change on every run
const readme = [
  '# n8n workflow backup',
  '',
  'Automatic mirror of an n8n instance, published by the "n8n to GitHub backup" workflow.',
  'Every run compares the content and only commits when something actually changed.',
  '',
  '- Current workflows: ' + liveCount + ' (' + activeCount + ' active), in `' + folder + '/`',
  '- Archived workflows: ' + archivedCount + ', in `' + folder + '/archives/`',
  '- Credentials: never exported, only their IDs and names appear inside nodes',
  '- Pinned data and staticData: excluded',
  '',
  '## Restoring a workflow',
  '',
  'In n8n: Workflows, Import from File, pick the JSON file.',
  'The `id` field is preserved, so importing overwrites the existing workflow when that id still exists.',
  '',
  '## Current workflows',
  '',
  '| Workflow | ID | Status | Nodes | File |',
  '| --- | --- | --- | --- | --- |'
].concat(liveRows).concat([
  '',
  '## Archived workflows',
  '',
  '| Workflow | ID | Nodes | File |',
  '| --- | --- | --- | --- |'
]).concat(archivedRows).join('\n') + '\n';

files.push({ path: 'README.md', content: readme });

const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');

return [{
  json: {
    files: files,
    fileCount: files.length,
    workflowCount: workflows.length,
    liveCount: liveCount,
    archivedCount: archivedCount,
    activeCount: activeCount,
    commitMessage: 'n8n backup ' + stamp + ' UTC: ' + liveCount + ' workflows (' + activeCount + ' active) + ' + archivedCount + ' archived'
  }
}];

// ==========================================================
// Build the Git Tree payload: additions, updates, deletions
// base_tree keeps everything that lives outside the workflows folder
// ==========================================================

const cfg = $('Configuration').first().json;
const folder = cfg.folder || 'workflows';
const prepared = $('Normalise workflows').first().json;

const current = $input.first().json;

if (current.truncated === true) {
  throw new Error('GitHub tree truncated: repository too large to read in a single call');
}

const baseTreeSha = $('Read current commit').first().json.tree.sha;

const wanted = {};
const tree = [];

for (let i = 0; i < prepared.files.length; i++) {
  const f = prepared.files[i];
  wanted[f.path] = true;
  tree.push({ path: f.path, mode: '100644', type: 'blob', content: f.content });
}

// Drop orphan exports: workflow deleted in n8n, or renamed
const existing = Array.isArray(current.tree) ? current.tree : [];
let removed = 0;

for (let j = 0; j < existing.length; j++) {
  const entry = existing[j];
  if (entry.type !== 'blob') { continue; }
  if (entry.path.indexOf(folder + '/') !== 0) { continue; }
  if (wanted[entry.path]) { continue; }
  tree.push({ path: entry.path, mode: '100644', type: 'blob', sha: null });
  removed++;
}

return [{
  json: {
    baseTreeSha: baseTreeSha,
    removedCount: removed,
    treePayload: { base_tree: baseTreeSha, tree: tree }
  }
}];
